def getProbability(balls):
    from math import factorial
    half = sum(balls) // 2
    # state: (balls in box 1, distinct(box1) - distinct(box2)) -> sum of 1/prod(a_i! * b_i!)
    states = {(0, 0): 1.0}
    for c in balls:
        nxt = {}
        for (s, d), w in states.items():
            for a in range(c + 1):
                if s + a > half:
                    break
                b = c - a
                key = (s + a, d + (a > 0) - (b > 0))
                nxt[key] = nxt.get(key, 0.0) + w / (factorial(a) * factorial(b))
        states = nxt
    total = sum(w for (s, d), w in states.items() if s == half)
    valid = states.get((half, 0), 0.0)
    return valid / total
